// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, CopyIcon, RefreshCwIcon, SaveIcon, XIcon } from 'lucide-react'

import { DemoStage, PanelChrome, Toggle, type Build } from '@/app/demos/stage'

import { esc } from '../_shared'
import {
  BATCH,
  CAPTIONS,
  CHARSETS,
  COPIED,
  COUNT,
  DEFAULT_LENGTH,
  FIRST,
  LENGTH,
  OPTIONS,
} from './script'

const ON = OPTIONS.map((option) => option.key !== 'excludeAmbiguous')

const build: Build = ({ tl, q, qa, step, final, move, click, type, scramble, wait, cursorOut }) => {
  const toggle = (index: number, on: boolean) => {
    move(`opt-${index}`)
    click(`opt-${index}`)
    tl.to(q(`opt-${index}-fill`), { opacity: on ? 1 : 0, duration: 0.2 }, '<')
    tl.to(q(`opt-${index}-knob`), { x: on ? 12 : 0, duration: 0.25, ease: 'back.out(2)' }, '<')
  }
  const generate = () => {
    move('generate')
    click('generate')
    tl.to(q('generate-icon'), { rotation: '+=360', duration: 0.6, ease: 'power2.inOut' }, '<')
  }

  ON.forEach((on, index) => {
    if (!on) return
    tl.set(q(`opt-${index}-knob`), { x: 12 }, 0)
    tl.set(q(`opt-${index}-fill`), { opacity: 1 }, 0)
  })

  step(0)
  move('length', { at: 0.2 })
  click('length')
  tl.to(q('length-text'), { text: '', duration: 0.1 }, '<')
  type('length-text', String(LENGTH), { speed: 0.12 })

  step(1, '+=0.3')
  generate()
  tl.fromTo(q('output'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '<0.1')
  tl.fromTo(q('row-first'), { opacity: 0 }, { opacity: 1, duration: 0.2 }, '<')
  scramble('pw-first', esc(FIRST), {
    at: '<',
    duration: 1,
    chars: CHARSETS.full.replace(/[<>&]/g, ''),
  })

  step(2, '+=0.6')
  toggle(3, false)
  toggle(4, true)
  move('count')
  click('count')
  tl.to(q('count-text'), { text: String(COUNT), duration: 0.15 }, '<0.1')
  generate()
  tl.to(q('row-first'), { opacity: 0, duration: 0.2 }, '<')
  tl.fromTo(
    qa('row-batch'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.08, ease: 'power2.out' },
    '<0.1',
  )
  BATCH.forEach((password, index) =>
    scramble(`pw-${index}`, password, {
      at: index === 0 ? '<' : '<0.08',
      duration: 0.9,
      chars: CHARSETS.plain,
    }),
  )

  step(3, '+=0.6')
  move(`copy-${COPIED}`)
  click(`copy-${COPIED}`)
  tl.to(q(`copy-${COPIED}`), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q(`done-${COPIED}`),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
    '<',
  )
  tl.to(q(`row-${COPIED}`), { borderColor: 'rgba(52,211,153,0.5)', duration: 0.2 }, '<')
  cursorOut('+=0.3')
  final()
  wait(1.4)
}

function NumberBox({ d, value, label }: { d: string; value: number; label: string }) {
  return (
    <span className="flex items-center gap-2 text-[10.5px] text-ink-soft">
      {label}
      <span
        data-d={d}
        className="flex h-7 w-14 items-center rounded-md border border-line-strong bg-canvas/80 px-2 font-mono text-[11px] text-ink"
      >
        <span data-d={`${d}-text`}>{value}</span>
      </span>
    </span>
  )
}

function Row({
  d,
  textD,
  index,
  className,
}: {
  d: string
  textD: string
  index?: number
  className?: string
}) {
  return (
    <div
      data-d={d}
      className={`${className ?? ''} mb-1 flex h-[22px] items-center justify-between gap-1 overflow-hidden rounded border border-line bg-white/[0.03] px-2 opacity-0`}
    >
      <code data-d={textD} className="min-w-0 flex-1 truncate font-mono text-[10.5px] text-ink" />
      {index == null ? (
        <CopyIcon className="size-3 text-muted" />
      ) : (
        <span className="relative size-3 text-muted">
          <span data-d={`copy-${index}`} className="absolute inset-0">
            <CopyIcon className="size-3" />
          </span>
          <span
            data-d={`done-${index}`}
            className="absolute inset-0 text-[var(--accent)] opacity-0"
          >
            <CheckIcon className="size-3" />
          </span>
        </span>
      )}
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Password Generator making a 24-character password, then five without symbols or look-alike characters"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2">
          <div className="flex items-center gap-4">
            <NumberBox d="length" value={DEFAULT_LENGTH} label="Length" />
            <NumberBox d="count" value={1} label="Count" />
          </div>
          <div className="grid grid-cols-2 gap-x-3 gap-y-1.5">
            {OPTIONS.map((option, index) => (
              <span
                key={option.key}
                className="flex items-center gap-1.5 text-[10.5px] text-ink-soft"
              >
                <Toggle d={`opt-${index}`} />
                {option.label}
              </span>
            ))}
          </div>
          <span
            data-d="generate"
            className="flex h-7 w-fit items-center gap-1.5 rounded-md bg-[var(--accent)] px-3 text-[11px] font-medium text-canvas"
          >
            <span data-d="generate-icon" className="flex">
              <RefreshCwIcon className="size-3" />
            </span>
            Generate
          </span>
          <div data-d="output" className="min-h-0 flex-1 opacity-0">
            <div className="mb-1 flex items-center justify-between">
              <span className="text-[10.5px] font-medium text-ink">Output</span>
              <span className="flex gap-1.5 text-muted">
                <SaveIcon className="size-3" />
                <CopyIcon className="size-3" />
                <XIcon className="size-3" />
              </span>
            </div>
            <div className="relative">
              <Row d="row-first" textD="pw-first" className="absolute inset-x-0 top-0" />
              {BATCH.map((_, index) => (
                <Row key={index} d={`row-batch row-${index}`} textD={`pw-${index}`} index={index} />
              ))}
            </div>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
